func readBudget(reader io.Reader, max int64) ([]byte, error) {
	if max < 0 || max > 1024 {
		return nil, fmt.Errorf("invalid budget")
	}
	data, err := io.ReadAll(io.LimitReader(reader, max+1))
	if err != nil {
