type Groups struct{ Parent []int }

func (g *Groups) Find(id int) int {
	if g.Parent[id] != id {
		g.Parent[id] = g.Find(g.Parent[id])
	}
	return g.Parent[id]
}
func (g *Groups) Union(a, b int) {
	a = g.Find(a)
	b = g.Find(b)
	if a > b {
		a, b = b, a
	}
	g.Parent[b] = a
