func choose(n, k int) (*big.Int, error) {
	if n < 0 || k < 0 || k > n {
		return nil, fmt.Errorf("invalid combination")
	}
	if k > n-k {
		k = n - k
	}
	result := big.NewInt(1)
	for i := 1; i <= k; i++ {
		result.Mul(result, big.NewInt(int64(n-k+i)))
		result.Quo(result, big.NewInt(int64(i)))
	}
	return result, nil
}
