func plan(base, cap time.Duration, count int) ([]time.Duration, error) {
	if base <= 0 || cap < base || count < 0 || count > 100 {
		return nil, fmt.Errorf("invalid retry plan")
	}
	result := []time.Duration{}
	delay := base
	for i := 0; i < count; i++ {
		result = append(result, delay)
		if delay > cap/2 {
			delay = cap
		} else {
			delay *= 2
		}
	}
	return result, nil
}
