	if cfg.TLS && (cfg.Certificate == "" || cfg.Key == "") {
		issues = append(issues, "tls requires certificate and key")
	}
	if !cfg.TLS && (cfg.Certificate != "" || cfg.Key != "") {
		issues = append(issues, "tls paths require tls enabled")
	}
	return issues
}
